using System.Text.Json;

namespace Strata.Quota;

/// <summary>
/// Turns a Codex app-server <c>account/rateLimits/read</c> result (or an <c>account/rateLimits/updated</c>
/// notification) into a <see cref="QuotaSnapshot"/>. Only quota facts are kept: the account id, upsell banner,
/// reset-credit titles and anything path-like in the response are dropped here and never stored.
/// Schema: the app-server protocol's GetAccountRateLimitsResponse / RateLimitSnapshot (generated by
/// <c>codex app-server generate-ts</c>).
/// </summary>
public static class CodexRateLimits
{
    public const string SourceName = "Codex app-server";

    public static QuotaSnapshot Parse(JsonElement result, DateTimeOffset observedAt)
    {
        if (result.ValueKind != JsonValueKind.Object || !result.TryGetProperty("rateLimits", out var single) || single.ValueKind != JsonValueKind.Object)
            throw new QuotaSourceException(QuotaErrorKind.BadResponse, "Codex returned rate limits in a shape Strata does not recognise.");

        var buckets = new List<JsonElement>();
        if (result.TryGetProperty("rateLimitsByLimitId", out var byId) && byId.ValueKind == JsonValueKind.Object)
            foreach (var p in byId.EnumerateObject())
                if (p.Value.ValueKind == JsonValueKind.Object) buckets.Add(p.Value);
        if (buckets.Count == 0) buckets.Add(single);

        var windows = buckets.SelectMany(BucketWindows).ToList();
        var main = buckets.FirstOrDefault(b => (Str(b, "limitId") ?? "codex") == "codex");
        if (main.ValueKind != JsonValueKind.Object) main = single;

        bool? allowed = Bool(result, "ordinaryUsageAllowed");
        string? reached = buckets.Select(b => Str(b, "rateLimitReachedType")).FirstOrDefault(r => r is not null);
        bool spendReached = buckets.Any(b => Bool(b, "spendControlReached") == true);
        return new QuotaSnapshot
        {
            Provider = QuotaProvider.Codex,
            Source = SourceName,
            Plan = PlanName(buckets.Select(b => Str(b, "planType")).FirstOrDefault(p => p is not null)),
            Windows = windows,
            Credits = Credits(main) ?? buckets.Select(Credits).FirstOrDefault(c => c is not null),
            ResetCredits = ResetCredits(result),
            // ordinaryUsageAllowed null means unknown; the protocol says never to infer it from percentages.
            Blocked = allowed is bool a ? !a : spendReached ? true : null,
            BlockedReason = ReachedReason(reached) ?? (spendReached ? "Spend control limit reached" : allowed == false ? "Usage not allowed right now" : null),
            ObservedAt = observedAt,
        };
    }

    /// <summary>
    /// Applies a sparse <c>account/rateLimits/updated</c> notification: windows it carries replace the ones with the
    /// same id; anything it leaves null keeps its last value (a rolling update never clears what was observed).
    /// </summary>
    public static QuotaSnapshot Merge(QuotaSnapshot? last, JsonElement notification, DateTimeOffset observedAt)
    {
        if (notification.ValueKind != JsonValueKind.Object || !notification.TryGetProperty("rateLimits", out var snap) || snap.ValueKind != JsonValueKind.Object)
            throw new QuotaSourceException(QuotaErrorKind.BadResponse, "Codex sent a rate-limit update in an unknown shape.");
        var incoming = BucketWindows(snap).ToList();
        var windows = (last?.Windows ?? []).Where(w => incoming.All(n => n.Id != w.Id)).Concat(incoming)
            .OrderBy(w => w.Id, StringComparer.Ordinal).ToList();
        string? reached = Str(snap, "rateLimitReachedType");
        return new QuotaSnapshot
        {
            Provider = QuotaProvider.Codex,
            Source = SourceName,
            Plan = PlanName(Str(snap, "planType")) ?? last?.Plan,
            Windows = windows,
            Credits = Credits(snap) ?? last?.Credits,
            ResetCredits = last?.ResetCredits,
            Blocked = reached is not null ? true : Bool(snap, "spendControlReached") == true ? true : last?.Blocked,
            BlockedReason = ReachedReason(reached) ?? last?.BlockedReason,
            ObservedAt = observedAt,
        };
    }

    /// <summary>Maps a JSON-RPC error (or transport failure text) to something the UI can explain.</summary>
    public static QuotaErrorKind Classify(string? message)
    {
        string m = (message ?? "").ToLowerInvariant();
        if (m.Contains("401") || m.Contains("unauthorized") || m.Contains("not logged in") || m.Contains("login required")
            || m.Contains("sign in") || m.Contains("token expired") || m.Contains("refresh token")) return QuotaErrorKind.SignInRequired;
        if (m.Contains("429") || m.Contains("too many requests")) return QuotaErrorKind.RateLimited;
        if (m.Contains("network") || m.Contains("connection") || m.Contains("dns") || m.Contains("offline")
            || m.Contains("error sending request") || m.Contains("timed out")) return QuotaErrorKind.Offline;
        return QuotaErrorKind.Failed;
    }

    private static IEnumerable<QuotaWindow> BucketWindows(JsonElement bucket)
    {
        string limitId = Str(bucket, "limitId") ?? "codex";
        string? prefix = limitId == "codex" ? null : Str(bucket, "limitName") ?? ModelName(Str(bucket, "normalModelSlug")) ?? limitId;
        foreach (string slot in new[] { "primary", "secondary" })
        {
            if (!bucket.TryGetProperty(slot, out var w) || w.ValueKind != JsonValueKind.Object) continue;
            if (!w.TryGetProperty("usedPercent", out var usedEl) || usedEl.ValueKind != JsonValueKind.Number)
                throw new QuotaSourceException(QuotaErrorKind.BadResponse, $"Codex {slot} window has no numeric usedPercent.");
            int? minutes = Int(w, "windowDurationMins");
            var (label, kind) = QuotaFormat.DurationLabel(minutes);
            double used = usedEl.GetDouble();
            yield return new QuotaWindow
            {
                Id = $"{limitId}/{slot}",
                Label = prefix is null ? label : $"{prefix} · {label.ToLowerInvariant()}",
                Kind = prefix is null ? kind : QuotaWindowKind.Model,
                ReportedUsedPercent = used,
                ResetsAt = Epoch(w, "resetsAt"),
                WindowMinutes = minutes,
                Reached = used >= 100,
            };
        }
        if (bucket.TryGetProperty("individualLimit", out var spend) && spend.ValueKind == JsonValueKind.Object
            && spend.TryGetProperty("remainingPercent", out var rem) && rem.ValueKind == JsonValueKind.Number)
        {
            yield return new QuotaWindow
            {
                Id = $"{limitId}/spend",
                Label = prefix is null ? "Spend limit" : $"{prefix} · spend limit",
                Kind = QuotaWindowKind.Spend,
                ReportedRemainingPercent = rem.GetDouble(),
                ResetsAt = Epoch(spend, "resetsAt"),
                Reached = Bool(bucket, "spendControlReached") == true,
                Detail = Str(spend, "used") is { } used && Str(spend, "limit") is { } limit ? $"{used} of {limit} used" : null,
            };
        }
    }

    private static QuotaCredits? Credits(JsonElement bucket)
    {
        if (!bucket.TryGetProperty("credits", out var c) || c.ValueKind != JsonValueKind.Object) return null;
        return new QuotaCredits(Bool(c, "hasCredits"), Bool(c, "unlimited"), Str(c, "balance"), "credits", null, null);
    }

    private static ResetCreditsInfo? ResetCredits(JsonElement result)
    {
        if (!result.TryGetProperty("rateLimitResetCredits", out var r) || r.ValueKind != JsonValueKind.Object) return null;
        long count = r.TryGetProperty("availableCount", out var n) && n.ValueKind == JsonValueKind.Number ? n.GetInt64() : 0;
        DateTimeOffset? next = null;
        if (r.TryGetProperty("credits", out var list) && list.ValueKind == JsonValueKind.Array)
            next = list.EnumerateArray().Where(c => Str(c, "status") == "available").Select(c => Epoch(c, "expiresAt"))
                .Where(e => e is not null).Min();
        return new ResetCreditsInfo(count, next);
    }

    private static string? ReachedReason(string? type) => type switch
    {
        null => null,
        "rate_limit_reached" => "Usage limit reached",
        "workspace_owner_credits_depleted" or "workspace_member_credits_depleted" => "Workspace credits used up",
        "workspace_owner_usage_limit_reached" or "workspace_member_usage_limit_reached" => "Workspace usage limit reached",
        _ => "Limit reached",
    };

    /// <summary>Plan names as people say them ("prolite" is Pro Lite); unknown values pass through.</summary>
    public static string? PlanName(string? plan) => plan switch
    {
        null or "unknown" => null,
        "free" => "Free", "go" => "Go", "plus" => "Plus", "pro" => "Pro", "prolite" => "Pro Lite", "promax" => "Pro Max",
        "team" => "Team", "business" => "Business", "enterprise" => "Enterprise", "edu" => "Edu",
        _ => string.Join(' ', plan.Split('_', StringSplitOptions.RemoveEmptyEntries)
            .Select(w => char.ToUpperInvariant(w[0]) + w[1..])),
    };

    /// <summary>"gpt-5.5-pro" reads "GPT-5.5 Pro"; "gpt-5.1-codex-max" reads "GPT-5.1 Codex Max".</summary>
    public static string? ModelName(string? slug)
    {
        if (string.IsNullOrWhiteSpace(slug)) return null;
        var parts = slug.Split('-', StringSplitOptions.RemoveEmptyEntries).ToList();
        string head = "";
        if (parts.Count >= 2 && parts[0].Equals("gpt", StringComparison.OrdinalIgnoreCase)) { head = "GPT-" + parts[1]; parts.RemoveRange(0, 2); }
        var words = parts.Select(w => char.IsLetter(w[0]) ? char.ToUpperInvariant(w[0]) + w[1..] : w);
        return string.Join(' ', new[] { head }.Concat(words).Where(w => w.Length > 0));
    }

    private static string? Str(JsonElement o, string name) =>
        o.ValueKind == JsonValueKind.Object && o.TryGetProperty(name, out var v) && v.ValueKind == JsonValueKind.String ? v.GetString() : null;

    private static bool? Bool(JsonElement o, string name) =>
        o.ValueKind == JsonValueKind.Object && o.TryGetProperty(name, out var v) && v.ValueKind is JsonValueKind.True or JsonValueKind.False ? v.GetBoolean() : null;

    private static int? Int(JsonElement o, string name) =>
        o.TryGetProperty(name, out var v) && v.ValueKind == JsonValueKind.Number && v.TryGetInt32(out int i) ? i : null;

    private static DateTimeOffset? Epoch(JsonElement o, string name) =>
        o.ValueKind == JsonValueKind.Object && o.TryGetProperty(name, out var v) && v.ValueKind == JsonValueKind.Number && v.TryGetInt64(out long s)
            ? DateTimeOffset.FromUnixTimeSeconds(s) : null;
}
